import { useEffect } from 'react'
import { ArrowLeft } from 'lucide-react'
import { GENRES } from '../data/genres'
import { useCatalog } from '../lib/catalog-context'
import { SeriesCard } from '../components/SeriesCard'
import { navigate } from '../lib/router'
import { cx, slugify } from '../lib/utils'
import { setSeo, buildBrowseMeta } from '../lib/seo'
import type { Series } from '../types'

/**
 * /browse/{kind}/{genre} — kind×genre combo hub ("action manhwa",
 * "romance manhua"). The genre pages mix both kinds; these pages target the
 * kind-qualified queries. Mirrored by the prerenderer's browse pages.
 */
export default function BrowsePage({ kind, genre }: { kind: string; genre: string }) {
  const { series: catalog, loading } = useCatalog()

  const genreName = GENRES.find((g) => slugify(g.name) === genre)?.name
  const validKind = kind === 'manhwa' || kind === 'manhua'

  const list = catalog
    .filter(
      (s) =>
        (s.kind ?? 'manhwa') === kind &&
        s.genres?.some((g) => g.toLowerCase() === genreName?.toLowerCase()),
    )
    .sort((a, b) => b.weeklyViews - a.weeklyViews)

  useEffect(() => {
    if (genreName && validKind) setSeo(buildBrowseMeta(genreName, kind, list.length))
  }, [genreName, validKind, kind, list.length])

  if (!loading && (!genreName || !validKind)) {
    return (
      <main className="mx-auto max-w-[1240px] px-4 py-24 text-center sm:px-6 lg:px-8">
        <h1 className="text-2xl font-extrabold">Category not found</h1>
        <button
          onClick={() => navigate('/genres')}
          className="mt-6 rounded-full bg-accent px-5 py-2.5 text-sm font-bold text-white"
        >
          Browse genres
        </button>
      </main>
    )
  }

  const kindLabel = kind === 'manhwa' ? 'Manhwa' : 'Manhua'

  return (
    <main className="animate-fade-up">
      <div
        className="border-b border-line"
        style={{ background: 'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)' }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate(`/${kind}`)}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> All {kindLabel.toLowerCase()}
          </button>
          <div className="eyebrow text-accent">{kindLabel}</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            {genreName} {kindLabel}
          </h1>
          <p className="mt-3 max-w-xl text-white/70">
            {loading ? '…' : `${list.length} ${genreName} ${kindLabel.toLowerCase()}, ranked by what everyone is reading.`}
          </p>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
          {list.map((s: Series) => (
            <SeriesCard key={s.id} series={s} />
          ))}
        </div>
      </div>
    </main>
  )
}
